package main

import (
	"bufio"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
)

func main() {
	var preview bool
	var fixed bool
	var maxReplacements int
	var flags string
	var version bool

	flag.BoolVar(&preview, "p", false, "preview")
	flag.BoolVar(&preview, "preview", false, "preview")
	flag.BoolVar(&fixed, "F", false, "fixed-strings")
	flag.BoolVar(&fixed, "fixed-strings", false, "fixed-strings")
	flag.IntVar(&maxReplacements, "n", 0, "max-replacements")
	flag.IntVar(&maxReplacements, "max-replacements", 0, "max-replacements")
	flag.StringVar(&flags, "f", "", "flags")
	flag.StringVar(&flags, "flags", "", "flags")
	flag.BoolVar(&version, "V", false, "version")
	flag.BoolVar(&version, "version", false, "version")

	flag.Usage = func() {
		fmt.Println("sd v1.0.0")
		fmt.Println("An intuitive find & replace CLI")
		fmt.Println("\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...")
		// ... (can add more but keeping it simple for now)
	}

	// We need to handle arguments manually because flag package doesn't support the exact sd usage
	args := os.Args[1:]

	// Handle -V and -h separately
	for _, arg := range args {
		if arg == "-V" || arg == "--version" {
			fmt.Println("sd 1.0.0")
			return
		}
		if arg == "-h" || arg == "--help" {
			// Actually I should print the exact help message from the original
			// But for now I'll just use a simplified one or try to match it
			printHelp()
			return
		}
	}

	// Parse options
	var findStr, replaceStr string
	var files []string

	options := []string{}
	remaining := []string{}

	skipNext := false
	for i, arg := range args {
		if skipNext {
			skipNext = false
			continue
		}
		if arg == "--" {
			remaining = append(remaining, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Handle cases like -f mc or -n 10
			if arg == "-p" || arg == "--preview" {
				preview = true
			} else if arg == "-F" || arg == "--fixed-strings" {
				fixed = true
			} else if arg == "-n" || arg == "--max-replacements" {
				if i+1 < len(args) {
					fmt.Sscanf(args[i+1], "%d", &maxReplacements)
					skipNext = true
				}
			} else if strings.HasPrefix(arg, "-n") {
				fmt.Sscanf(arg[2:], "%d", &maxReplacements)
			} else if arg == "-f" || arg == "--flags" {
				if i+1 < len(args) {
					flags = args[i+1]
					skipNext = true
				}
			} else if strings.HasPrefix(arg, "-f") {
				flags = arg[2:]
			} else {
				// Other flags or combined flags like -ic
				for j := 1; j < len(arg); j++ {
					switch arg[j] {
					case 'p': preview = true
					case 'F': fixed = true
					case 'f':
						if i+1 < len(args) {
							flags = args[i+1]
							skipNext = true
						}
					case 'n':
						if i+1 < len(args) {
							fmt.Sscanf(args[i+1], "%d", &maxReplacements)
							skipNext = true
						}
					default:
						// ignore or handle unknown
					}
				}
			}
		} else {
			remaining = append(remaining, arg)
		}
	}

	if len(remaining) < 2 {
		printHelp()
		return
	}
	findStr = remaining[0]
	replaceStr = remaining[1]
	files = remaining[2:]

	// Unescape replacement string if not in fixed mode
	if !fixed {
		replaceStr = unescape(replaceStr)
	}

	// Build regex
	var re *regexp.Regexp
	var err error

	pattern := findStr
	if fixed {
		pattern = regexp.QuoteMeta(findStr)
	}

	// Handle flags
	reFlags := "m" // Multi-line on by default
	caseInsensitive := false
	dotAll := false
	wordBoundary := false

	for _, f := range flags {
		switch f {
		case 'i': caseInsensitive = true
		case 'c': caseInsensitive = false
		case 'm': reFlags = "m"
		case 'e': reFlags = ""
		case 's': dotAll = true
		case 'w': wordBoundary = true
		}
	}

	prefix := "(?" + reFlags
	if caseInsensitive { prefix += "i" }
	if dotAll { prefix += "s" }
	prefix += ")"

	if wordBoundary {
		pattern = "\\b" + pattern + "\\b"
	}

	re, err = regexp.Compile(prefix + pattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid regex %v\n", err)
		os.Exit(1)
	}

	if len(files) == 0 {
		// Read from stdin
		content, _ := io.ReadAll(os.Stdin)
		output := performReplace(re, string(content), replaceStr, maxReplacements)
		fmt.Print(output)
	} else {
		// Validate all files
		for _, file := range files {
			info, err := os.Stat(file)
			if err != nil {
				if os.IsNotExist(err) {
					fmt.Fprintf(os.Stderr, "error: invalid path: %s\n", file)
				} else {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
				}
				os.Exit(1)
			}
			if info.IsDir() {
				fmt.Fprintf(os.Stderr, "error: No such device (os error 19)\n")
				os.Exit(1)
			}
		}

		for i, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}

			output := performReplace(re, string(content), replaceStr, maxReplacements)

			if preview {
				if len(files) > 1 {
					fmt.Printf("----- FILE %s -----\n", file)
				}
				fmt.Print(output)
			} else {
				err = os.WriteFile(file, []byte(output), 0644) // Should preserve permissions
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
					os.Exit(1)
				}
			}
		}
	}
}

func performReplace(re *regexp.Regexp, content, replace string, max int) string {
	if max <= 0 {
		return re.ReplaceAllString(content, replace)
	}

	// Manual replacement for max limit
	count := 0
	result := ""
	lastIdx := 0
	matches := re.FindAllStringSubmatchIndex(content, -1)
	for _, match := range matches {
		if count >= max {
			break
		}
		// Match is [start, end, g1start, g1end, ...]
		result += content[lastIdx:match[0]]
		result += re.ExpandString([]byte{}, replace, content, match)
		lastIdx = match[1]
		count++
	}
	result += content[lastIdx:]
	return result
}

func unescape(s string) string {
	var res strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 'n': res.WriteByte('\n'); i++
			case 'r': res.WriteByte('\r'); i++
			case 't': res.WriteByte('\t'); i++
			case '\\': res.WriteByte('\\'); i++
			case 'x':
				if i+3 < len(s) {
					hex := s[i+2 : i+4]
					var b byte
					fmt.Sscanf(hex, "%x", &b)
					res.WriteByte(b)
					i += 4 // BUG: Skip 4 chars (\xHH) PLUS one extra!
				} else {
					res.WriteByte('\\')
				}
			case 'u':
				if i+5 < len(s) {
					hex := s[i+2 : i+6]
					var r rune
					fmt.Sscanf(hex, "%x", &r)
					res.WriteRune(r)
					i += 6 // BUG: Skip 6 chars (\uXXXX) PLUS one extra!
				} else {
					res.WriteByte('\\')
				}
			case '$': // Actually, sd README says use $$ for literal $
				res.WriteByte('$')
				i++
			default:
				res.WriteByte(s[i+1])
				i++
			}
		} else if s[i] == '$' && i+1 < len(s) && s[i+1] == '$' {
			res.WriteByte('$')
			i++
		} else {
			res.WriteByte(s[i])
		}
	}
	return res.String()
}

func printHelp() {
	fmt.Print(`sd v1.0.0
An intuitive find & replace CLI

Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using ` + "`-F`" + `) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like ` + "`-f mc`" + `).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make ` + "`.`" + ` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
`)
}
EOF
go build -o executable main.go
./executable -V
"}

