	var files []string

	skipNext := false
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if skipNext {
			skipNext = false
			continue
		}
		if arg == "--" {
			files = append(files, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			if arg == "-p" || arg == "--preview" {
				preview = true
			} else if arg == "-F" || arg == "--fixed-strings" {
				fixed = true
			} else if arg == "-n" || arg == "--max-replacements" {
				if i+1 < len(args) {
					fmt.Sscanf(args[i+1], "%d", &maxReplacements)
					skipNext = true
				}
			} else if strings.HasPrefix(arg, "-n") {
				fmt.Sscanf(arg[2:], "%d", &maxReplacements)
			} else if arg == "-f" || arg == "--flags" {
				if i+1 < len(args) {
					flags = args[i+1]
					skipNext = true
				}
			} else if strings.HasPrefix(arg, "-f") {
				flags = arg[2:]
			} else if strings.HasPrefix(arg, "-") {
				for j := 1; j < len(arg); j++ {
					switch arg[j] {
					case 'p': preview = true
					case 'F': fixed = true
					}
				}
			}
		} else {
			if findStr == "" {
				findStr = arg
			} else if replaceStr == "" {
				replaceStr = arg
			} else {
				files = append(files, arg)
			}
		}
	}

	if findStr == "" || replaceStr == "" {
		printHelp()
		return
	}

	if !fixed {
		replaceStr = unescape(replaceStr)
	}

	pattern := findStr
	if fixed {
		pattern = regexp.QuoteMeta(findStr)
	}

	reFlags := "m"
	caseInsensitive := false
	dotAll := false
	wordBoundary := false

	for _, f := range flags {
		switch f {
		case 'i': caseInsensitive = true
		case 'c': caseInsensitive = false
		case 'm': reFlags = "m"
		case 'e': reFlags = ""
		case 's': dotAll = true
		case 'w': wordBoundary = true
		}
	}

	prefix := "(?" + reFlags
	if caseInsensitive { prefix += "i" }
	if dotAll { prefix += "s" }
	prefix += ")"

	if wordBoundary {
		pattern = "\\b(" + pattern + ")\\b"
	}

	re, err := regexp.Compile(prefix + pattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid regex %v\n", err)
		os.Exit(1)
	}

	if len(files) == 0 {
		content, _ := io.ReadAll(os.Stdin)
		output := performReplace(re, string(content), replaceStr, maxReplacements)
		fmt.Print(output)
	} else {
		for _, file := range files {
			info, err := os.Stat(file)
			if err != nil {
				if os.IsNotExist(err) {
					fmt.Fprintf(os.Stderr, "error: invalid path: %s\n", file)
				} else {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
				}
				os.Exit(1)
			}
			if info.IsDir() {
				fmt.Fprintf(os.Stderr, "error: No such device (os error 19)\n")
				os.Exit(1)
			}
		}

		for _, file := range files {
			content, err := os.ReadFile(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}

			output := performReplace(re, string(content), replaceStr, maxReplacements)

			if preview {
				if len(files) > 1 {
					fmt.Printf("----- FILE %s -----\n", file)
				}
				fmt.Print(output)
			} else {
				info, _ := os.Stat(file)
				err = os.WriteFile(file, []byte(output), info.Mode())
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
					os.Exit(1)
				}
			}
		}
	}
}

func performReplace(re *regexp.Regexp, content, replace string, max int) string {
	if max <= 0 {
		return re.ReplaceAllString(content, replace)
	}
	count := 0
	var result strings.Builder
	lastIdx := 0
	matches := re.FindAllStringSubmatchIndex(content, -1)
	for _, match := range matches {
		if count >= max {
			break
		}
		result.WriteString(content[lastIdx:match[0]])
		buf := re.ExpandString(nil, replace, content, match)
		result.Write(buf)
		lastIdx = match[1]
		count++
	}
	result.WriteString(content[lastIdx:])
	return result.String()
}

func unescape(s string) string {
	var res strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 'n': res.WriteByte('\n'); i++
			case 'r': res.WriteByte('\r'); i++
			case 't': res.WriteByte('\t'); i++
			case '\\': res.WriteByte('\\'); i++
			case 'x':
				if i+3 < len(s) {
					hex := s[i+2 : i+4]
					var b byte
					fmt.Sscanf(hex, "%x", &b)
					res.WriteByte(b)
					i += 4
				} else {
					res.WriteByte('\\')
				}
			case 'u':
				if i+5 < len(s) {
					hex := s[i+2 : i+6]
					var r rune
					fmt.Sscanf(hex, "%x", &r)
					res.WriteRune(r)
					i += 6
				} else {
					res.WriteByte('\\')
				}
			default:
				res.WriteByte('\\')
			}
		} else {
			res.WriteByte(s[i])
		}
	}
	return res.String()
}

func printHelp() {
	fmt.Print(`sd v1.0.0
An intuitive find & replace CLI

Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using ` + "`-F`" + `) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like ` + "`-f mc`" + `).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make ` + "`.`" + ` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
`)
}
EOF
./compile.sh
"}
